        "Amount": 300,
        "Percentage": 10.0
      },
      {
        "Category": "Utilities",
        "Amount": 200,
        "Percentage": 6.7
      }
    ]
  },
  "elements": {
    "budgetScreen": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "headerStack",
        "summaryText",
        "breakdownTitle",
        "budgetTable",
        "sectionDivider"
      ]
    },
    "headerStack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "pieChartIcon",
        "mainTitle"
      ]
    },
    "pieChartIcon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000728_01_1_pie-chart.svg"
      },
      "children": []
    },
    "mainTitle": {
      "type": "Text",
      "props": {
        "text": "Monthly Budget Overview",
        "variant": "h1"
      },
      "children": []
    },
    "summaryText": {
      "type": "Text",
      "props": {
        "text": "Your total allocated budget is $3,000. The largest expense category is Rent, accounting for half of your total budget."
      },
      "children": []
    },
    "breakdownTitle": {
      "type": "Text",
      "props": {
        "text": "Budget Allocation Breakdown",
        "variant": "h2"
      },
      "children": []
    },
    "budgetTable": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "Category",
            "label": "Category"
          },
          {
            "key": "Amount",
            "label": "Amount"
          },
          {
            "key": "Percentage",
            "label": "Percentage"
          }
        ],
        "statePath": "/budgetData",
        "domain": "generic",
        "preferredPresentation": "table",
        "numericColumns": [
          "Amount",
          "Percentage"
        ]
      },
      "children": []
    },
    "sectionDivider": {
      "type": "Divider",
      "props": {},
      "children": []
    }
  }
}
